function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function money($v){return number_format((float)$v,2,',','.').' €';}
function ensure_catalog_columns(PDO $pdo){
  $needed=[
    'category'=>"VARCHAR(80) NOT NULL DEFAULT 'Otros'",
    'format'=>"VARCHAR(120) NULL",
    'units_per_box'=>"INT UNSIGNED NOT NULL DEFAULT 0"
  ];
  $st=$pdo->prepare("SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='bonilla_products' AND COLUMN_NAME=?");
  foreach($needed as $col=>$definition){$st->execute([$col]);if(!(int)$st->fetchColumn()){$pdo->exec("ALTER TABLE bonilla_products ADD COLUMN `$col` $definition");}}
}

function ensure_order_columns(PDO $pdo){
  $needed=[
    'receive_date'=>"DATE NULL",
    'subtotal'=>"DECIMAL(10,2) NOT NULL DEFAULT 0.00",
    'vat_total'=>"DECIMAL(10,2) NOT NULL DEFAULT 0.00",
    'total'=>"DECIMAL(10,2) NOT NULL DEFAULT 0.00",
    'include_vat'=>"TINYINT(1) NOT NULL DEFAULT 1",
    'discount'=>"DECIMAL(10,2) NOT NULL DEFAULT 0.00",
    'payment_status'=>"VARCHAR(20) NOT NULL DEFAULT 'pendiente'",
    'payment_date'=>"DATE NULL",
    'payment_method'=>"VARCHAR(30) NULL",
    'albaran_number'=>"VARCHAR(80) NULL",
    'request_token'=>"VARCHAR(64) NULL"
  ];
  $st=$pdo->prepare("SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='bonilla_orders' AND COLUMN_NAME=?");
  foreach($needed as $col=>$definition){$st->execute([$col]);if(!(int)$st->fetchColumn()){$pdo->exec("ALTER TABLE bonilla_orders ADD COLUMN `$col` $definition");}}
  $idx=$pdo->query("SHOW INDEX FROM bonilla_orders")->fetchAll(PDO::FETCH_ASSOC);
  $names=array_column($idx,'Key_name');
  if(!in_array('uq_bonilla_orders_request_token',$names,true)) $pdo->exec("ALTER TABLE bonilla_orders ADD UNIQUE KEY uq_bonilla_orders_request_token (request_token)");
  if(!in_array('uq_bonilla_orders_albaran',$names,true)) $pdo->exec("ALTER TABLE bonilla_orders ADD UNIQUE KEY uq_bonilla_orders_albaran (albaran_number)");
  // Existing orders from older versions receive an albaran number and payment state once.
  $missing=(int)$pdo->query("SELECT COUNT(*) FROM bonilla_orders WHERE albaran_number IS NULL OR albaran_number=''")->fetchColumn();
  if($missing){
    $rows=$pdo->query("SELECT id FROM bonilla_orders WHERE albaran_number IS NULL OR albaran_number='' ORDER BY id")->fetchAll(PDO::FETCH_COLUMN);
    $next=(int)$pdo->query("SELECT COALESCE(MAX(CAST(SUBSTRING(albaran_number,5) AS UNSIGNED)),-1)+1 FROM bonilla_orders WHERE albaran_number REGEXP '^Alb-[0-9]+$'")->fetchColumn();
    $up=$pdo->prepare("UPDATE bonilla_orders SET albaran_number=? WHERE id=?");
    foreach($rows as $id){$up->execute(['Alb-'.$next,(int)$id]);$next++;}
  }
  $pdo->exec("UPDATE bonilla_orders SET payment_status=CASE WHEN payment_status IS NULL OR payment_status='' THEN 'pendiente' ELSE payment_status END");
  // Migrate the old payment state into the order so historical cobros are not lost.
  try { $pdo->exec("UPDATE bonilla_orders o JOIN (SELECT order_id, MAX(paid) paid, MAX(payment_date) payment_date, MAX(payment_method) payment_method FROM bonilla_delivery_notes WHERE order_id IS NOT NULL GROUP BY order_id) n ON n.order_id=o.id SET o.payment_status=CASE WHEN n.paid=1 THEN 'cobrado' ELSE o.payment_status END, o.payment_date=CASE WHEN n.paid=1 THEN n.payment_date ELSE o.payment_date END, o.payment_method=CASE WHEN n.paid=1 THEN n.payment_method ELSE o.payment_method END"); } catch(Throwable $ignore) {}
}
function next_albaran_number(PDO $pdo){
  $n=(int)$pdo->query("SELECT COALESCE(MAX(CAST(SUBSTRING(albaran_number,5) AS UNSIGNED)),-1)+1 FROM bonilla_orders WHERE albaran_number REGEXP '^Alb-[0-9]+$'")->fetchColumn();
  return 'Alb-'.$n;
}
