  if($a==='actualizar_cesta'){ $pid=(int)($_POST['product_id']??0); $qty=(float)($_POST['quantity']??0); if($pid && isset($_SESSION['cesta'][$pid])){ if($qty<=0) unset($_SESSION['cesta'][$pid]); else $_SESSION['cesta'][$pid]['quantity']=$qty; } $page='cesta'; }
  if($a==='add_cesta'){ $pid=(int)($_POST['product_id']??0); $qty=max(1,(float)($_POST['quantity']??1)); if($pid){ $st=$pdo->prepare('SELECT id,name,price,vat,image_path FROM bonilla_products WHERE id=? AND active=1'); $st->execute([$pid]); if($prod=$st->fetch()){ $_SESSION['cesta']=$_SESSION['cesta']??[]; if(isset($_SESSION['cesta'][$pid])) $_SESSION['cesta'][$pid]['quantity']+=$qty; else $_SESSION['cesta'][$pid]=['id'=>$prod['id'],'name'=>$prod['name'],'price'=>$prod['price'],'vat'=>$prod['vat'],'image_path'=>$prod['image_path'],'quantity'=>$qty]; $msg='Producto añadido a la cesta.'; }} $page='productos'; }
  if($a==='importar_productos'){if(!empty($_FILES['catalogo']['tmp_name'])){$h=fopen($_FILES['catalogo']['tmp_name'],'r');$head=fgetcsv($h,0,';');if(!$head)$head=fgetcsv($h,0,',');$head=array_map(fn($v)=>strtolower(trim((string)$v)),$head?:[]);$map=array_flip($head);$count=0;while(($row=fgetcsv($h,0,';'))!==false){if(count($row)<2){continue;}$name=trim($row[$map['nombre']??0]??'');if(!$name)continue;$vals=[$name,(float)str_replace(',','.',$row[$map['precio']??4]??0),(float)str_replace(',','.',$row[$map['coste']??5]??0),(float)str_replace(',','.',$row[$map['iva']??6]??21),trim($row[$map['unidad']??8]??'unidad'),trim($row[$map['sku']??1]??''),trim($row[$map['descripcion']??9]??''),trim($row[$map['categoria']??2]??'Otros'),trim($row[$map['formato']??3]??''),(int)($row[$map['unidades_por_caja']??7]??0),1,0];$st=$pdo->prepare('INSERT INTO bonilla_products(name,price,cost_price,vat,unit,sku,description,category,format,units_per_box,active,sort_order) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$st->execute($vals);$count++;}fclose($h);$msg="Productos importados: $count";$page='productos';}}if($a==='eliminar_producto'){ $id=(int)($_POST['id']??0); if($id){$st=$pdo->prepare('DELETE FROM bonilla_products WHERE id=?');$st->execute([$id]);$msg='Producto eliminado correctamente.';} $page='productos'; } if($a==='producto'){ ensure_catalog_columns($pdo); $id=(int)($_POST['id']??0); $image=null; if(!empty($_FILES['image']['name']) && is_uploaded_file($_FILES['image']['tmp_name'])){ $dir=__DIR__.'/assets/products'; if(!is_dir($dir)) mkdir($dir,0755,true); $ext=strtolower(pathinfo($_FILES['image']['name'],PATHINFO_EXTENSION)); if(in_array($ext,['jpg','jpeg','png','webp'])){ $image='assets/products/'.uniqid('prod_').'.'.$ext; move_uploaded_file($_FILES['image']['tmp_name'],__DIR__.'/'.$image); }} $d=[trim($_POST['name']), (float)$_POST['price'],(float)$_POST['cost_price'],(float)$_POST['vat'],trim($_POST['unit']),trim($_POST['sku']),trim($_POST['description']),trim($_POST['category']??'Otros'),trim($_POST['format']??''),(int)($_POST['units_per_box']??0),isset($_POST['active'])?1:0,(int)$_POST['sort_order']]; if($id){$s=$pdo->prepare('UPDATE bonilla_products SET name=?,price=?,cost_price=?,vat=?,unit=?,sku=?,description=?,category=?,format=?,units_per_box=?,active=?,sort_order=?'.($image?', image_path=?':'').' WHERE id=?');$args=[...$d];if($image)$args[]=$image;$args[]=$id;$s->execute($args);}else{$s=$pdo->prepare('INSERT INTO bonilla_products(name,price,cost_price,vat,unit,sku,description,category,format,units_per_box,active,sort_order) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$s->execute($d);} $msg='Producto guardado correctamente.'; $page='productos'; }
