<?php if($page==='cliente' && $detail):?><div class="toolbar"><div><a class="back" href="?page=clientes">← Volver a clientes</a><h2><?=e($detail['business_name'])?></h2><p><?=e($detail['address']?:'Sin dirección registrada')?></p></div><a class="btn" href="?page=pedidos&client_id=<?=$detail['id']?>">+ Crear pedido</a></div><?php $cs=$pdo->prepare('SELECT COALESCE(SUM(total),0) ventas,COUNT(*) pedidos FROM bonilla_orders WHERE client_id=?');$cs->execute([$detail['id']]);$cstats=$cs->fetch();$ps=$pdo->prepare("SELECT COALESCE(SUM(total),0) total,COALESCE(SUM(CASE WHEN payment_status='cobrado' THEN total ELSE 0 END),0) cobrado,COALESCE(SUM(CASE WHEN payment_status='pendiente' THEN total ELSE 0 END),0) pendiente FROM bonilla_orders WHERE client_id=?");$ps->execute([$detail['id']]);$pstats=$ps->fetch();$cp=$pdo->prepare("SELECT COALESCE(SUM((o.subtotal-o.discount) - COALESCE((SELECT SUM(oi.quantity*COALESCE(p.cost_price,0)) FROM bonilla_order_items oi LEFT JOIN bonilla_products p ON p.id=oi.product_id WHERE oi.order_id=o.id),0)),0) estimada,COALESCE(SUM(CASE WHEN o.payment_status='cobrado' THEN (o.subtotal-o.discount) - COALESCE((SELECT SUM(oi.quantity*COALESCE(p.cost_price,0)) FROM bonilla_order_items oi LEFT JOIN bonilla_products p ON p.id=oi.product_id WHERE oi.order_id=o.id),0) ELSE 0 END),0) real FROM bonilla_orders o WHERE o.client_id=?");$cp->execute([$detail['id']]);$cprofit=$cp->fetch();?><section class="cards client-commercial-stats"><div class="stat"><span>Pedidos</span><b><?=e($cstats['pedidos'])?></b><small>Histórico</small></div><div class="stat"><span>Ventas</span><b><?=money($cstats['ventas'])?></b><small>Total vendido</small></div><div class="stat"><span>Cobrado</span><b><?=money($pstats['cobrado'])?></b><small>Ya cobrado</small></div><div class="stat"><span>Pendiente</span><b><?=money($pstats['pendiente'])?></b><small>Por cobrar</small></div><div class="stat neon-profit"><span>Ganancia estimada</span><b><?=money($cprofit['estimada'])?></b><small>Ventas menos coste</small></div><div class="stat neon-profit real"><span>Ganancia real</span><b><?=money($cprofit['real'])?></b><small>Solo pedidos cobrados</small></div></section><section class="detail-grid"><div class="panel profile"><div class="avatar"><?=e(strtoupper(substr($detail['business_name'],0,1)))?></div><h2><?=e($detail['business_name'])?></h2><span class="pill <?=($detail['active']?'ok':'off')?>"><?=e($statusLabels[$detail['commercial_status']]??$detail['commercial_status'])?></span><div class="contact-list"><p><b>Contacto</b><?=e($detail['contact_person']?:'No indicado')?></p><p><b>Teléfono</b><?=e($detail['phone']?:'No indicado')?></p><p><b>Dirección</b><?=e($detail['address']?:'No indicada')?></p></div><form class="route-assign-form" method="post"><input type="hidden" name="accion" value="asignar_ruta_cliente"><input type="hidden" name="client_id" value="<?=$detail['id']?>"><label>Ruta comercial<select name="route_id"><option value="0">Sin ruta asignada</option><?php foreach($routes as $rt):?><option value="<?=$rt['id']?>" <?=((int)($detail['route_id']??0)===(int)$rt['id'])?'selected':''?>><?=e($rt['name'])?></option><?php endforeach;?></select></label><button class="btn secondary">Guardar ruta</button></form><a class="btn secondary" href="?page=clientes&edit=<?=$detail['id']?>">Editar ficha</a></div><div class="panel"><h2>Seguimiento comercial</h2><div class="mini-grid"><div><small>Última visita</small><strong><?=e($detail['last_visit']?:'Pendiente')?></strong></div><div><small>Próxima visita</small><strong><?=e($detail['next_visit']?:'Sin programar')?></strong></div></div><h3>Observaciones</h3><p class="notes"><?=nl2br(e($detail['notes']?:'Sin observaciones.'))?></p><h2>Historial de pedidos</h2><table><tr><th>Pedido</th><th>Fecha</th><th>Estado</th><th>Cobro</th><th>Total</th><th>Acciones</th></tr><?php $q=$pdo->prepare('SELECT * FROM bonilla_orders WHERE client_id=? ORDER BY (payment_status=\'cobrado\') ASC,id DESC');$q->execute([$detail['id']]);foreach($q as $r):?><tr><td><strong>#<?=e($r['id'])?></strong><small><?=e($r['albaran_number']??'Sin albarán')?></small></td><td><?=e($r['order_date'])?></td><td><span class="pill"><?=e(ucfirst($r['status']))?></span></td><td><span class="pill <?=($r['payment_status']==='cobrado'?'ok':'off')?>"><?=($r['payment_status']==='cobrado'?'Cobrado':'Pendiente')?></span></td><td><strong><?=money($r['total']??0)?></strong></td><td><a href="?page=pedidos&edit=<?=$r['id']?>">Ver</a> · <a href="?page=pedidos&edit=<?=$r['id']?>">Editar</a> · <a href="nota_entrega.php?id=<?=$r['id']?>" target="_blank">Albarán</a></td></tr><?php endforeach;?></table></div></section><?php endif;?>
<?php if($page==='clientes' && $edit):?><div class="toolbar"><div><a class="back" href="?page=clientes">← Volver a clientes</a><h2>Editar ficha comercial</h2></div></div><form class="form panel" method="post"><input type="hidden" name="accion" value="cliente"><input type="hidden" name="id" value="<?=$edit['id']?>"><div class="grid"><label>Nombre del negocio<input required name="business_name" value="<?=e($edit['business_name'])?>"></label><label>Persona de contacto<input name="contact_person" value="<?=e($edit['contact_person']??'')?>"></label><label>Teléfono<input name="phone" value="<?=e($edit['phone']??'')?>"></label><label>Dirección<input name="address" value="<?=e($edit['address']??'')?>"></label><label>Localidad<input name="localidad" value="<?=e($edit['localidad']??'')?>" placeholder="Algeciras, Los Barrios..."></label><label>Estado comercial<select name="commercial_status"><?php foreach($statusLabels as $k=>$v):?><option value="<?=$k?>" <?=($edit['commercial_status']??'pendiente')===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label>Última visita<input type="date" name="last_visit" value="<?=e($edit['last_visit']??'')?>"></label><label>Próxima visita<input type="date" name="next_visit" value="<?=e($edit['next_visit']??'')?>"></label></div><label>Observaciones<textarea name="notes"><?=e($edit['notes']??'')?></textarea></label><button>Guardar ficha</button></form><?php endif;?><?php if($page==='clientes'):$localidadFiltro=trim($_GET['localidad']??'');$estadoFiltro=trim($_GET['estado']??'');$visitaFiltro=trim($_GET['visita']??'');$pagoFiltro=trim($_GET['pago']??'');$pedidoFiltro=trim($_GET['pedido']??'');$localidades=$pdo->query("SELECT DISTINCT localidad FROM bonilla_clients WHERE localidad IS NOT NULL AND localidad<>'' ORDER BY localidad")->fetchAll();$sql="SELECT c.*, (SELECT COUNT(*) FROM bonilla_orders n WHERE n.client_id=c.id AND n.payment_status='pendiente') AS pending_payments, (SELECT COUNT(*) FROM bonilla_orders o WHERE o.client_id=c.id AND o.status IN ('pendiente','nuevo')) AS pending_orders FROM bonilla_clients c WHERE 1=1";$args=[];if($localidadFiltro){$sql.=' AND c.localidad=?';$args[]=$localidadFiltro;}if($estadoFiltro){$sql.=' AND c.commercial_status=?';$args[]=$estadoFiltro;}if($visitaFiltro==='pendiente')$sql.=" AND (c.next_visit IS NULL OR c.next_visit='' OR c.next_visit<=CURDATE())";if($pagoFiltro==='pendiente')$sql.=" AND EXISTS (SELECT 1 FROM bonilla_orders n2 WHERE n2.client_id=c.id AND n2.payment_status='pendiente')";if($pedidoFiltro==='pendiente')$sql.=" AND EXISTS (SELECT 1 FROM bonilla_orders o2 WHERE o2.client_id=c.id AND o2.status IN ('pendiente','nuevo'))";$ordenClientes=$_GET['orden']??'nombre';$dirClientes=strtolower($_GET['dir']??'asc')==='desc'?'desc':'asc';$allowedOrders=['nombre'=>"c.business_name",'estado'=>"CASE c.commercial_status WHEN 'pendiente' THEN 1 WHEN 'seguimiento' THEN 2 WHEN 'contactado' THEN 3 WHEN 'activo' THEN 4 WHEN 'no_interesado' THEN 5 ELSE 9 END,c.business_name",'visita'=>"CASE WHEN c.next_visit IS NULL OR c.next_visit='' THEN 1 ELSE 0 END,c.next_visit,c.business_name",'localidad'=>"c.localidad,c.business_name"];if(!isset($allowedOrders[$ordenClientes]))$ordenClientes='nombre';$sql.=' ORDER BY '.$allowedOrders[$ordenClientes].' '.$dirClientes;$st=$pdo->prepare($sql);$st->execute($args);$clientes=$st->fetchAll();$clientesSortUrl=function($campo)use($ordenClientes,$dirClientes,$localidadFiltro,$estadoFiltro,$visitaFiltro,$pagoFiltro,$pedidoFiltro){$next=($ordenClientes===$campo&&$dirClientes==='asc')?'desc':'asc';return '?page=clientes&orden='.rawurlencode($campo).'&dir='.$next.'&localidad='.rawurlencode($localidadFiltro).'&estado='.rawurlencode($estadoFiltro).'&visita='.rawurlencode($visitaFiltro).'&pago='.rawurlencode($pagoFiltro).'&pedido='.rawurlencode($pedidoFiltro);};?><div class="toolbar"><div><p>Gestiona tu cartera y el seguimiento de cada establecimiento.</p></div><a class="btn" href="#cliente-form">+ Nuevo cliente</a></div><form class="filters panel" method="get"><input type="hidden" name="page" value="clientes"><input class="quick-search" placeholder="Buscar cliente..." oninput="filtrarClientes(this.value)"><select name="localidad"><option value="">Todas las localidades</option><?php foreach($localidades as $l):?><option value="<?=e($l['localidad'])?>" <?=$localidadFiltro===$l['localidad']?'selected':''?>><?=e($l['localidad'])?></option><?php endforeach;?></select><select name="estado"><option value="">Todos los estados</option><?php foreach($statusLabels as $k=>$v):?><option value="<?=$k?>" <?=$estadoFiltro===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select><select name="visita"><option value="">Todas las visitas</option><option value="pendiente" <?=$visitaFiltro==='pendiente'?'selected':''?>>Pendientes de visitar</option></select><select name="pago"><option value="">Todos los pagos</option><option value="pendiente" <?=$pagoFiltro==='pendiente'?'selected':''?>>Pendientes de pago</option></select><select name="pedido"><option value="">Todos los pedidos</option><option value="pendiente" <?=$pedidoFiltro==='pendiente'?'selected':''?>>Pendientes de pedido</option></select><button>Filtrar</button></form><div class="panel"><div class="selection-bar"><label><input type="checkbox" id="select-all" onchange="seleccionarTodos(this)"> Seleccionar todos</label><span id="selected-count">0 seleccionados</span></div><div class="bulk-actions"><button type="button" onclick="accionClientes('visita')">Marcar visitados</button><button type="button" onclick="accionClientes('pedido')">Crear pedido</button><button type="button" onclick="accionClientes('cobro')">Registrar cobro</button></div><table id="clients-table"><tr><th></th><th><a class="sort-head <?=($ordenClientes==='nombre'?'active':'')?>" href="<?=$clientesSortUrl('nombre')?>">Negocio <?=($ordenClientes==='nombre'?( $dirClientes==='asc'?'↑':'↓'):'↕')?></a></th><th>Contacto</th><th><a class="sort-head <?=($ordenClientes==='estado'?'active':'')?>" href="<?=$clientesSortUrl('estado')?>">Estado <?=($ordenClientes==='estado'?( $dirClientes==='asc'?'↑':'↓'):'↕')?></a></th><th><a class="sort-head <?=($ordenClientes==='visita'?'active':'')?>" href="<?=$clientesSortUrl('visita')?>">Próxima visita <?=($ordenClientes==='visita'?( $dirClientes==='asc'?'↑':'↓'):'↕')?></a></th><th></th></tr><?php foreach($clientes as $r):?><tr class="client-row"><td><input type="checkbox" class="client-check" onchange="actualizarSeleccion()" value="<?=$r['id']?>"></td><td><a class="strong-link" href="?page=cliente&id=<?=$r['id']?>"><?=e($r['business_name'])?></a><small><?=e($r['address'])?></small></td><td><?=e($r['phone'])?><small><?=e($r['contact_person']??'')?></small></td><td><span class="pill <?=($r['active']?'ok':'off')?>"><?=e($statusLabels[$r['commercial_status']??'pendiente']??'Pendiente')?></span></td><td><?=e($r['next_visit']??'—')?></td><td><a href="?page=clientes&edit=<?=$r['id']?>">Editar</a> · <a href="?page=clientes&delete=cliente&id=<?=$r['id']?>" onclick="return confirm('¿Eliminar este cliente?')">Eliminar</a><?php if(!empty($r['phone'])):?><br><a href="tel:<?=e($r['phone'])?>">Llamar</a><?php endif;?></td></tr><?php endforeach;?></table></div><?php if(!$edit):?><form id="cliente-form" class="form panel" method="post"><h2>Nuevo cliente</h2><input type="hidden" name="accion" value="cliente"><input type="hidden" name="id" value="<?=$edit['id']??0?>"><div class="grid"><label>Nombre del negocio<input required name="business_name" value="<?=e($edit['business_name']??'')?>"></label><label>Persona de contacto<input name="contact_person" value="<?=e($edit['contact_person']??'')?>"></label><label>Teléfono<input name="phone" value="<?=e($edit['phone']??'')?>"></label><label>Dirección<input name="address" value="<?=e($edit['address']??'')?>"></label><label>Localidad<input name="localidad" value="<?=e($edit['localidad']??'')?>" placeholder="Algeciras, Los Barrios..."></label><label>Estado comercial<select name="commercial_stat