<div id="pedido-modal" class="modal-overlay" onclick="cerrarPedido(event)"><div class="modal-box" onclick="event.stopPropagation()"><button type="button" class="modal-close" onclick="cerrarPedido()">×</button><form id="pedido-form" class="form panel modal-form" method="post" onsubmit="bloquearPedido(this)"><h2><?=$orderEdit?'Editar pedido #'.$orderEdit['id']:'Nuevo pedido'?></h2><input type="hidden" name="accion" value="pedido"><input type="hidden" name="order_id" value="<?=$orderEdit['id']??0?>"><input type="hidden" name="request_token" value="<?=e($orderEdit['request_token']??($_SESSION['pedido_token']??new_request_token()))?>"><div class="grid"><label>Cliente<select required name="client_id"><option value="">Selecciona un cliente</option><?php foreach($pdo->query('SELECT id,business_name,localidad,commercial_status FROM bonilla_clients ORDER BY business_name') as $c):?><option value="<?=$c['id']?>" <?=((int)($orderEdit['client_id']??($_GET['client_id']??0))===$c['id'])?'selected':''?>><?=e($c['business_name'])?><?=!empty($c['localidad'])?' · '.e($c['localidad']):''?></option><?php endforeach;?></select></label><label>Fecha de recepción<input type="date" name="receive_date" value="<?=e($orderEdit['receive_date']??'')?>"></label><label>Estado<select name="status"><option value="pendiente" <?=($orderEdit['status']??'pendiente')==='pendiente'?'selected':''?>>Pendiente</option><option value="preparado" <?=($orderEdit['status']??'')==='preparado'?'selected':''?>>Preparado</option><option value="entregado" <?=($orderEdit['status']??'')==='entregado'?'selected':''?>>Entregado</option><option value="cancelado" <?=($orderEdit['status']??'')==='cancelado'?'selected':''?>>Cancelado</option></select></label><label>IVA<select name="include_vat"><option value="1" <?=((int)($orderEdit['include_vat']??1)===1)?'selected':''?>>IVA incluido</option><option value="0" <?=((int)($orderEdit['include_vat']??1)===0)?'selected':''?>>Sin IVA</option></select></label><label>Descuento (€)<input type="number" step="0.01" min="0" name="discount" value="<?=e($orderEdit['discount']??0)?>"></label><label>Notas<input name="notes" value="<?=e($orderEdit['notes']??'')?>"></label></div><div class="order-lines"><?php foreach($pdo->query('SELECT * FROM bonilla_products WHERE active=1 ORDER BY name') as $p):?><label class="line"><span class="product-cell"><?php if(!empty($p['image_path'])):?><img class="product-thumb" src="<?=e($p['image_path'])?>" alt="<?=e($p['name'])?>"><?php else:?><span class="product-thumb placeholder">📦</span><?php endif;?><span><strong><?=e($p['name'])?></strong><small><?=money($p['price'])?> · IVA <?=$p['vat']?>%</small></span></span><input type="hidden" name="product_id[]" value="<?=$p['id']?>"><input type="number" min="0" step="0.01" name="quantity[]" value="<?=e($selected[(int)$p['id']]??'')?>" placeholder="0"></label><?php endforeach;?></div><button id="pedido-submit"><?=$orderEdit?'Guardar cambios':'Crear pedido'?></button></form></div></div><?php endif;?>
<?php if($page==='cobros'): $rows=$pdo->query("SELECT o.*,c.business_name FROM bonilla_orders o LEFT JOIN bonilla_clients c ON c.id=o.client_id ORDER BY (o.payment_status='pendiente') DESC,o.order_date DESC,o.id DESC")->fetchAll(); $pending=0;$paidTotal=0;$sales=0;$costs=0;$estimated=0;$real=0; foreach($rows as $r){$sales+=max(0,(float)$r['subtotal']-(float)$r['discount']);$st=$pdo->prepare("SELECT COALESCE(SUM(oi.quantity*COALESCE(p.cost_price,0)),0) FROM bonilla_order_items oi LEFT JOIN bonilla_products p ON p.id=oi.product_id WHERE oi.order_id=?");$st->execute([$r['id']]);$cost=(float)$st->fetchColumn();$costs+=$cost;$profit=((float)$r['subtotal']-(float)$r['discount'])-$cost;$estimated+=$profit;if(($r['payment_status']??'pendiente')==='cobrado'){$paidTotal+=(float)$r['total'];$real+=$profit;}else{$pending+=(float)$r['total'];}} ?>
<div class="toolbar"><div><p>Control de cobros y rentabilidad. Todo sale directamente de los pedidos.</p></div><a class="btn secondary" href="?page=pedidos">Ir a pedidos</a></div>
<section class="cards"><div class="stat"><span>Pendiente de cobro</span><b><?=money($pending)?></b><small>Pedidos aún no cobrados</small></div><div class="stat accent"><span>Cobrado</span><b><?=money($paidTotal)?></b><small>Pedidos cobrados</small></div><div class="stat"><span>Precio Producto</span><b><?=money($sales)?></b><small>Venta sin IVA y sin ganancias</small></div><div class="stat"><span>Ganancias Estimadas</span><b><?=money($estimated)?></b><small>Venta neta menos coste</small></div><div class="stat accent"><span>Ganancias Reales</span><b><?=money($real)?></b><small>Solo lo cobrado menos coste</small></div></section>
<div class="panel cobros-panel"><h2>Control de cobros</h2><table><tr><th>Pedido</th><th>Albarán</th><th>Cliente</th><th>Precio Producto</th><th>Ganancia Estimada</th><th>Ganancia Real</th><th>Estado</th><th>Acciones</th></tr><?php foreach($rows as $r): $st=$pdo->prepare("SELECT COALESCE(SUM(oi.quantity*COALESCE(p.cost_price,0)),0) FROM bonilla_order_items oi LEFT JOIN bonilla_products p ON p.id=oi.product_id WHERE oi.order_id=?");$st->execute([$r['id']]);$cost=(float)$st->fetchColumn();$sale=max(0,(float)$r['subtotal']-(float)$r['discount']);$profit=$sale-$cost;$isPaid=($r['payment_status']??'pendiente')==='cobrado';?><tr><td>#<?=e($r['id'])?></td><td><?=e($r['albaran_number']??'—')?></td><td><?=e($r['business_name']??'Sin cliente')?></td><td><strong><?=money($sale)?></strong></td><td><?=money($profit)?></td><td><?=$isPaid?'<strong>'.money($profit).'</strong>':'—'?></td><td><span class="pill <?=$isPaid?'ok':'off'?>"><?=$isPaid?'Cobrado':'Pendiente de cobro'?></span></td><td><a class="btn small-btn" href="?page=pedidos&edit=<?=$r['id']?>">Editar</a> <a class="btn small-btn secondary" href="nota_entrega.php?id=<?=$r['id']?>" target="_blank">Albarán</a><?php if(!$isPaid):?><form method="post" style="display:inline"><input type="hidden" name="accion" value="cobro"><input type="hidden" name="order_id" value="<?=$r['id']?>"><input type="hidden" name="paid" value="1"><input type="hidden" name="payment_date" value="<?=date('Y-m-d')?>"><button class="btn small-btn">Cobrado</button></form><?php else:?><form method="post" style="display:inline"><input type="hidden" name="accion" value="cobro"><input type="hidden" name="order_id" value="<?=$r['id']?>"><input type="hidden" name="paid" value="0"><button class="link-button">Marcar pendiente</button></form><?php endif;?></td></tr><?php endforeach;?></table></div><?php endif;?>
</main></div><script>if("serviceWorker" in navigator){navigator.serviceWorker.register("sw.js").catch(function(){})}</script><nav class="mobile-nav"><a href="?page=inicio">Inicio</a><a href="?page=clientes">Clientes</a><a href="?page=pedidos">Nuevo pedido</a><a href="?page=cobros">Cobros</a></nav><script>function seleccionarTodos(x){document.querySelectorAll(".client-check").forEach(c=>c.checked=x.checked);actualizarSeleccion()}function actualizarSeleccion(){let n=[...document.querySelectorAll(".client-check:checked")].length;let e=document.getElementById("selected-count");if(e)e.textContent=n+" seleccionados"}function filtrarClientes(q){q=q.toLowerCase();document.querySelectorAll(".client-row").forEach(r=>r.style.display=r.textContent.toLowerCase().includes(q)?"":"none")}function accionClientes(tipo){let ids=[...document.querySelectorAll(".client-check:checked")].map(x=>x.value);if(!ids.length){alert("Selecciona al menos un cliente.");return}if(tipo==="pedido"){location.href="?page=pedidos&client_id="+ids[0];return}let f=document.createElement("form");f.method="post";f.innerHTML="<input name=accion value=clientes_masivo><input name=tipo value="+tipo+">"+ids.map(id=>"<input name=ids[] value="+id+">").join("");document.body.appendChild(f);f.submit()}function abrirProducto(){var m=document.getElementById("producto-modal");if(m)m.classList.add("open")}function cerrarProducto(e){if(e&&e.target!==e.currentTarget)return;var m=document.getElementById("producto-modal");if(m)m.classList.remove("open")}if(<?= $edit ? "true" : "false" ?>)abrirProducto();if(<?= $orderEdit ? "true" : "false" ?>)abrirPedido();function abrirPedido(){var m=document.getElementById("pedido-modal");if(m)m.classList.add("open")}function cerrarPedido(e){if(e&&e.target!==e.currentTarget)return;var m=document.getElementById("pedido-modal");if(m)m.classList.remove("open")};function bloquearPedido(f){var b=document.getElementById("pedido-submit");if(f.dataset.submitted==="1")return false;f.dataset.submitted="1";if(b){b.disabled=true;b.textContent="Guardando…";}return true};var routeSearch=document.getElementById("route-client-search");if(routeSearch){routeSearch.addEventListener("input",function(){var q=this.value.toLowerCase().trim();document.querySelectorAll(".route-client-row").forEach(function(r){r.style.display=r.textContent.toLowerCase().includes(q)?"":"none"})})}</script><div id="image-lightbox" class="image-lightbox" onclick="this.classList.remove('show')"><img id="image-lightbox-img" alt="Imagen ampliada"></div><script>function abrirImagen(src){document.getElementById("image-lightbox-img").src=src;document.getElementById("image-lightbox").classList.add("show");}</script></body></html>
